// BUG-003: Purchased items reappear in the cart after checkout
//
// Generated by EXEGEZIS 0.1.0 from test plan BUG-003 (sha256:4b2587d8c2d4…).
// Do not edit by hand. Regenerate with: exegezis compile --plan benchmarks/buggy-shop/cases/BUG-003/plan.json
// Standalone: it needs only @playwright/test. Run it with:
//   npx playwright test BUG-003.spec.ts
// Target: http://localhost:3000/ (override with the BASE_URL environment variable).
//
// Preconditions:
//   - buggy-shop is running at the target URL
//   - Every execution starts from a fresh browser context, hence a new session with an empty cart

import { expect, test, type Response } from "@playwright/test";

test.use({
  baseURL: process.env["BASE_URL"] ?? "http://localhost:3000/",
  viewport: { width: 1280, height: 720 },
  locale: "en-US",
  timezoneId: "UTC",
  actionTimeout: 10000,
  navigationTimeout: 30000,
});

test("BUG-003: Purchased items reappear in the cart after checkout", async ({ page }) => {
  test.setTimeout(120000);

  // Responses observed during the test, for HTTP assertions.
  const responses: Response[] = [];
  page.on("response", (response) => responses.push(response));

  await test.step("1. navigate /", async () => {
    await page.goto("/");
  });

  await test.step("2. click button \"Add Mechanical Keyboard to cart\"", async () => {
    await page.getByRole("button", { name: "Add Mechanical Keyboard to cart" }).click();
  });

  await test.step("3. anchor: The keyboard is in the cart", async () => {
    await expect(page.getByText("Mechanical Keyboard × 1")).toBeVisible({ timeout: 5000 });
  });

  await test.step("4. click button \"Checkout\"", async () => {
    await page.getByRole("button", { name: "Checkout" }).click();
  });

  await test.step("5. anchor: The order is confirmed", async () => {
    await expect(page.getByRole("heading", { name: "Order confirmed" })).toBeVisible({ timeout: 5000 });
  });

  await test.step("6. anchor: The server created the order", async () => {
    await expect.poll(() => lastResponse(responses, "POST", "/api/checkout")?.status(), { timeout: 5000 }).toBe(201);
  });

  await test.step("7. click button \"Continue shopping\"", async () => {
    await page.getByRole("button", { name: "Continue shopping" }).click();
  });

  await test.step("8. click button \"Add Wireless Mouse to cart\"", async () => {
    await page.getByRole("button", { name: "Add Wireless Mouse to cart" }).click();
  });

  await test.step("9. anchor: The newly added mouse is in the cart", async () => {
    await expect(page.getByText("Wireless Mouse × 1")).toBeVisible({ timeout: 5000 });
  });

  await test.step("10. expect: The already purchased keyboard is no longer in the cart", async () => {
    await expect(page.getByText("Mechanical Keyboard ×")).toHaveCount(0, { timeout: 2000 });
  });
});

/** Most recent response to `method path` observed so far (query string ignored). */
function lastResponse(responses: Response[], method: string | undefined, path: string): Response | undefined {
  for (let i = responses.length - 1; i >= 0; i--) {
    const response = responses[i]!;
    if (method !== undefined && response.request().method() !== method) continue;
    if (new URL(response.url()).pathname === path) return response;
  }
  return undefined;
}
